    add("T7_DETERMINISM","PROJECT",{"history":[history[1],history[0]],"profile_ref":"p","algorithm":"r6"},"INVALID_HISTORY")
    add("T7_DETERMINISM","PROJECT",{"history":[history[0],{**history[1],"sequence_no":2}],"profile_ref":"p","algorithm":"r6"},"MISSING_EVENT")
    negatives=[
      ("N-001","ENUM",{"domain":"EvaluationValue","value":"MAYBE"},"UNKNOWN_VALUE"),("N-002","ENUM",{"domain":"ValidationStatus","value":"ACCEPTED"},"UNKNOWN_VALUE"),
      ("N-003","BOUNDARY",{"claim":"VALID_TO_CONFORMANT","forbidden":True},"REJECTED"),("N-004","BOUNDARY",{"claim":"TRUE_TO_AUTHORIZED","forbidden":True},"REJECTED"),
      ("N-005","ERROR",{"code":"EVALUATOR_FAILURE","policy":{"mapping":"FALSE","explicit":True,"profile_ref":"p"}},"EVALUATION_FAILURE"),("N-006","ERROR",{"code":"EVALUATOR_TIMEOUT","policy":{"mapping":"UNKNOWN","explicit":False,"profile_ref":"p"}},"EVALUATION_FAILURE"),
      ("N-007","BOUNDARY",{"claim":"INSTRUCTION_AS_NORMATIVE_REQUIREMENT","forbidden":True},"REJECTED"),("N-008","BOUNDARY",{"claim":"PROFILE_ALTERS_NORMATIVE_MEANING","forbidden":True},"REJECTED"),
      ("N-009","BOUNDARY",{"claim":"ISSUED_TO_VALID","forbidden":True},"REJECTED"),("N-010","BOUNDARY",{"claim":"APPROVED_TO_SUCCEEDED","forbidden":True},"REJECTED"),
      ("N-011","BOUNDARY",{"claim":"INVALID_AUTHORITY_TO_AUTHORIZED","forbidden":True},"REJECTED"),("N-012","BOUNDARY",{"claim":"EXPIRED_AUTHORITY_TO_AUTHORIZED","forbidden":True},"REJECTED"),
      ("N-013","BOUNDARY",{"claim":"STALE_EVIDENCE_TO_TRUE","forbidden":True},"REJECTED"),("N-014","PROJECT",{"history":[{"sequence_no":0,"validated":False,"committed":True}],"profile_ref":"p","algorithm":"r6"},"INVALID_HISTORY"),
      ("N-015","PROJECT",{"history":[history[0],history[0]],"profile_ref":"p","algorithm":"r6"},"INVALID_HISTORY"),("N-016","PROJECT",{"history":[history[0],{**history[1],"sequence_no":2}],"profile_ref":"p","algorithm":"r6"},"MISSING_EVENT"),
      ("N-017","REUSE",{"old_basis":{"artifact":"a"},"new_basis":{"artifact":"b"}},"NOT_REUSABLE"),("N-018","ENUM",{"domain":"EvaluationValue","value":"__UNKNOWN__"},"UNKNOWN_VALUE")]
    for identifier,operation,data,expected in negatives:add("MINIMUM_NEGATIVE_SET",operation,data,expected,identifier)
    for number in range(1,19):add("MACHINE_INVARIANTS","INVARIANT",{"invariant_id":f"R6-I{number:02d}","condition":True},"SATISFIED")
