    if not (PRE/"INDEPENDENT-VALIDATION.yaml").is_file():raise RuntimeError("validated R5 predecessor required")
    if DEST.exists():raise RuntimeError("refusing to regenerate immutable v14.7-R6 package")
    prior=[{"path":str(p.relative_to(COMP)),"sha256":sha(p),"bytes":p.stat().st_size} for p in sorted(COMP.rglob("*")) if p.is_file()]
